import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ApiService } from '../../core/services/api.service';

@Component({
  selector: 'app-users',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div class="page-header"><div class="container"><h2>Quản lý Người dùng</h2></div></div>
    <section class="section">
      <div class="container">
        <div class="loading-spinner" *ngIf="loading"><div class="spinner"></div></div>
        <table class="data-table" *ngIf="!loading">
          <thead><tr><th>Họ tên</th><th>Email</th><th>Vai trò</th><th>Trạng thái</th><th>Ngày tạo</th><th>Hành động</th></tr></thead>
          <tbody>
            <tr *ngFor="let u of users">
              <td>{{ u.fullName }}</td>
              <td>{{ u.email }}</td>
              <td><span class="badge" [class.badge-danger]="u.role.name==='admin'" [class.badge-primary]="u.role.name==='user'">{{ u.role.name }}</span></td>
              <td><span class="badge" [class.badge-success]="u.isActive" [class.badge-danger]="!u.isActive">{{ u.isActive ? 'Active' : 'Inactive' }}</span></td>
              <td>{{ u.createdAt | date:'dd/MM/yyyy' }}</td>
              <td><button class="btn btn-sm btn-outline" (click)="toggle(u.id)" *ngIf="u.role.name!=='admin'">{{ u.isActive ? 'Vô hiệu' : 'Kích hoạt' }}</button></td>
            </tr>
          </tbody>
        </table>
      </div>
    </section>
  `
})
export class UsersComponent implements OnInit {
  users: any[] = [];
  loading = true;
  constructor(private api: ApiService) {}
  ngOnInit() { this.api.getUsers().subscribe((data: any) => { this.users = data.data; this.loading = false; }, () => { this.loading = false; }); }
  toggle(id: string) { this.api.toggleUserActive(id).subscribe(() => this.ngOnInit()); }
}
